/*Table structure for table `sk_attribute` */

DROP TABLE IF EXISTS `sk_attribute`;

CREATE TABLE `sk_attribute` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(100) COLLATE utf8_unicode_ci NOT NULL COMMENT '属性名称',
  `code` varchar(50) COLLATE utf8_unicode_ci NOT NULL COMMENT '属性编码',
  `type` enum('text','number','select','checkbox','range') COLLATE utf8_unicode_ci NOT NULL DEFAULT 'text' COMMENT '属性类型',
  `data_type` enum('string','number','boolean') COLLATE utf8_unicode_ci NOT NULL DEFAULT 'string' COMMENT '数据类型',
  `unit` varchar(20) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '单位',
  `options` text COLLATE utf8_unicode_ci COMMENT '选项值（JSON格式，用于select/checkbox类型）',
