/*Table structure for table `sk_category` */

DROP TABLE IF EXISTS `sk_category`;

CREATE TABLE `sk_category` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `parent_id` int(10) unsigned DEFAULT '0',
  `name` varchar(100) NOT NULL,
  `name_zh_hant` varchar(100) DEFAULT NULL,
  `slug` varchar(100) DEFAULT NULL,
  `icon` varchar(255) DEFAULT NULL,
  `sort` int(11) DEFAULT '0',
  `status` tinyint(4) NOT NULL DEFAULT '1',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `code` varchar(20) DEFAULT NULL,
  `path` varchar(100) DEFAULT NULL,
  `level` int(11) DEFAULT NULL,
  `is_leaf` int(11) DEFAULT '0',
  `category_name_en` varchar(30) DEFAULT NULL,
  `is_hot` int(11) DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_category_parent` (`parent_id`),
  KEY `idx_category_path` (`path`),
  KEY `idx_category_level` (`level`)
) ENGINE=InnoDB AUTO_INCREMENT=129 DEFAULT CHARSET=utf8mb4 COMMENT='Product Category Table';

