/*Table structure for table `sk_category_attribute` */

DROP TABLE IF EXISTS `sk_category_attribute`;

CREATE TABLE `sk_category_attribute` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `category_id` int(11) NOT NULL COMMENT '分类ID',
  `attribute_id` int(11) NOT NULL COMMENT '属性ID',
  `is_required` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否必填',
  `is_filter` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否作为筛选条件',
  `sort_order` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_category_attribute` (`category_id`,`attribute_id`),
  KEY `idx_category` (`category_id`),
  KEY `idx_attribute` (`attribute_id`)
) ENGINE=InnoDB AUTO_INCREMENT=51 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci COMMENT='分类-属性关联表';

