/*Table structure for table `sk_customer` */

DROP TABLE IF EXISTS `sk_customer`;

CREATE TABLE `sk_customer` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_name` varchar(100) NOT NULL,
  `logo` varchar(255) DEFAULT NULL,
  `contact_person` varchar(100) DEFAULT NULL,
  `position` varchar(100) DEFAULT NULL,
  `content` text,
  `content_en` text,
  `sort` int(11) DEFAULT '0',
  `status` tinyint(4) NOT NULL DEFAULT '1',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='Customer Testimonial Table';

/*Data for the table `sk_customer` */

insert  into `sk_customer`(`id`,`company_name`,`logo`,`contact_person`,`position`,`content`,`content_en`,`sort`,`status`,`create_time`,`update_time`) values 
(1,'华为技术有限公司','/images/customers/huawei.jpg','张经理','采购总监','天启芯的产品质量稳定，服务专业，是我们重要的合作伙伴。','Tianqi Xin products are of stable quality and professional service, they are our important partner.',10,1,'2025-12-19 10:00:00','2025-12-19 10:00:00'),
(2,'中兴通讯','/images/customers/zte.jpg','李总监','技术经理','技术支持响应及时，产品性能优越。','Technical support responds promptly and product performance is excellent.',20,1,'2025-12-19 10:00:00','2025-12-19 10:00:00'),
(3,'小米科技','/images/customers/xiaomi.jpg','王主管','供应链经理','合作多年，产品质量始终如一，值得信赖。','Years of cooperation, product quality has always been consistent and trustworthy.',30,1,'2025-12-19 10:00:00','2025-12-19 10:00:00');

/*Table structure for table `sk_dictionary_data` */

DROP TABLE IF EXISTS `sk_dictionary_data`;

CREATE TABLE `sk_dictionary_data` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '数据ID',
  `project_id` int(11) unsigned NOT NULL COMMENT '所属项目ID',
  `field_values` text NOT NULL COMMENT '字段值（JSON格式存储）',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1=启用，0=禁用',
  `sort_order` int(11) NOT NULL DEFAULT '0' COMMENT '排序值',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `delete_time` int(11) DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`),
  KEY `idx_project_id` (`project_id`),
  KEY `idx_status` (`status`),
  KEY `idx_sort` (`sort_order`),
  CONSTRAINT `fk_data_project` FOREIGN KEY (`project_id`) REFERENCES `sk_dictionary_project` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=53 DEFAULT CHARSET=utf8mb4 COMMENT='数据字典-数据表';

