/*Table structure for table `sk_faq` */

DROP TABLE IF EXISTS `sk_faq`;

CREATE TABLE `sk_faq` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT 'FAQ ID',
  `question` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '问题',
  `answer` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '答案',
  `category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'FAQ分类',
  `product_id` int(10) unsigned DEFAULT NULL COMMENT '关联产品ID',
  `sort` int(11) DEFAULT '0' COMMENT '排序',
  `views` int(11) DEFAULT '0' COMMENT '查看次数',
  `is_hot` tinyint(4) DEFAULT '0' COMMENT '是否热门：0-否，1-是',
  `status` tinyint(4) DEFAULT '1' COMMENT '状态：1-启用，0-禁用',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_category` (`category`),
  KEY `idx_product_id` (`product_id`),
  KEY `idx_is_hot` (`is_hot`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='FAQ常见问题表';

/*Data for the table `sk_faq` */

insert  into `sk_faq`(`id`,`question`,`answer`,`category`,`product_id`,`sort`,`views`,`is_hot`,`status`,`created_at`,`updated_at`) values 
(1,'如何购买红酒？','您可以通过我们的在线商城直接下单购买，选择您喜欢的酒款加入购物车，然后完成支付即可。','购买流程',NULL,1,0,1,1,'2025-11-26 09:43:11','2025-11-26 09:43:11'),
(2,'配送需要多长时间？','一般情况下，市内1-2个工作日送达，省内2-3个工作日，省外3-5个工作日。','配送服务',NULL,2,0,1,1,'2025-11-26 09:43:11','2025-11-26 09:43:11'),
(3,'如何保存红酒？','红酒应存放在阴凉、避光、湿度适中的环境中，最佳温度为12-18℃，平放或斜放以保持瓶塞湿润。','保存方法',NULL,3,0,0,1,'2025-11-26 09:43:11','2025-11-26 09:43:11'),
(4,'可以退换货吗？','收到商品7天内，如发现质量问题，可凭购买凭证办理退换货服务。','售后服务',NULL,4,0,1,1,'2025-11-26 09:43:11','2025-11-26 09:43:11'),
(5,'有会员优惠吗？','我们提供会员等级制度，不同等级享受不同折扣，具体可查看会员中心说明。','会员服务',NULL,5,0,0,1,'2025-11-26 09:43:11','2025-11-26 09:43:11');

/*Table structure for table `sk_inventory` */

DROP TABLE IF EXISTS `sk_inventory`;

CREATE TABLE `sk_inventory` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `supplier_id` int(10) unsigned DEFAULT '0' COMMENT '供应商ID',
  `product_id` int(11) NOT NULL COMMENT '产品ID',
  `storage_location_id` int(11) DEFAULT NULL COMMENT '库位ID',
  `quantity` int(11) NOT NULL DEFAULT '0' COMMENT '库存数量',
  `in_transit_quantity` int(11) DEFAULT '0' COMMENT '在途数量',
  `reserved_quantity` int(11) NOT NULL DEFAULT '0' COMMENT '预留数量',
  `available_quantity` int(11) NOT NULL DEFAULT '0' COMMENT '可用数量',
  `safety_stock` int(11) NOT NULL DEFAULT '0' COMMENT '安全库存',
  `in_transit_stock` int(11) NOT NULL DEFAULT '0' COMMENT '在途库存',
  `last_updated` datetime NOT NULL COMMENT '最后更新时间',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '更新时间',
  `warehouse_id` int(11) NOT NULL COMMENT '仓库ID',
  `batch_number` varchar(50) DEFAULT NULL COMMENT '批次号',
  `shelf_life` int(11) DEFAULT NULL COMMENT '保质期(天)',
  `production_date` date DEFAULT NULL COMMENT '生产日期',
  `expiry_date` date DEFAULT NULL COMMENT '过期日期',
  `cost_price` decimal(10,2) DEFAULT NULL COMMENT '成本价',
  `stock_status` enum('normal','warning','danger') NOT NULL DEFAULT 'normal' COMMENT '库存状态',
  PRIMARY KEY (`id`),
  KEY `idx_inventory_product` (`product_id`),
  KEY `idx_inventory_storage` (`storage_location_id`),
  KEY `idx_storage_location_id` (`storage_location_id`),
  KEY `idx_inventory_warehouse` (`warehouse_id`),
  KEY `idx_inventory_batch` (`batch_number`),
