/*Table structure for table `sk_job` */

DROP TABLE IF EXISTS `sk_job`;

CREATE TABLE `sk_job` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `job_title` varchar(255) NOT NULL,
  `department` varchar(100) DEFAULT NULL,
  `location` varchar(100) DEFAULT NULL,
  `job_type` varchar(50) DEFAULT NULL,
  `salary_range` varchar(100) DEFAULT NULL,
  `requirements` text,
  `responsibilities` text,
  `status` tinyint(4) NOT NULL DEFAULT '1',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COMMENT='Job Posting Table';

/*Data for the table `sk_job` */

insert  into `sk_job`(`id`,`job_title`,`department`,`location`,`job_type`,`salary_range`,`requirements`,`responsibilities`,`status`,`create_time`,`update_time`) values 
(6,'销售经理','销售部','上海','全职','10K-20K','大专及以上学历，2年以上销售经验','负责市场开拓和客户维护',0,'2025-11-06 08:47:28','0000-00-00 00:00:00'),
(9,'研发工程师','技术部','深圳','全职','15K-25K','本科及以上学历，3年以上相关工作经验','负责产品研发和技术创新',1,'2025-11-06 08:49:00','0000-00-00 00:00:00');

/*Table structure for table `sk_job_apply` */

DROP TABLE IF EXISTS `sk_job_apply`;

CREATE TABLE `sk_job_apply` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `job_id` int(10) unsigned NOT NULL,
  `name` varchar(100) NOT NULL,
  `email` varchar(100) NOT NULL,
  `phone` varchar(20) DEFAULT NULL,
  `resume_url` varchar(255) DEFAULT NULL,
  `cover_letter` text,
  `status` varchar(50) DEFAULT 'pending',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Job Application Table';

/*Data for the table `sk_job_apply` */

/*Table structure for table `sk_lang_code` */

DROP TABLE IF EXISTS `sk_lang_code`;

CREATE TABLE `sk_lang_code` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `type_id` int(11) NOT NULL DEFAULT '0' COMMENT '语言类型(FK→sk_lang_type.id)',
  `code` varchar(255) NOT NULL DEFAULT '' COMMENT '状态码(编号)',
  `remarks` varchar(255) NOT NULL DEFAULT '' COMMENT '中文备注标识(作为翻译key)',
  `lang_explain` varchar(255) NOT NULL DEFAULT '' COMMENT '翻译文本',
  `is_admin` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1=管理后台 2=用户前端',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_type_id` (`type_id`),
  KEY `idx_code` (`code`),
  KEY `idx_remarks` (`remarks`)
) ENGINE=InnoDB AUTO_INCREMENT=775 DEFAULT CHARSET=utf8mb4 COMMENT='语言码表';

