/*Table structure for table `sk_lang_country` */

DROP TABLE IF EXISTS `sk_lang_country`;

CREATE TABLE `sk_lang_country` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `type_id` int(5) NOT NULL DEFAULT '0' COMMENT '关联语言类型',
  `code` varchar(50) NOT NULL DEFAULT '' COMMENT '浏览器语言标识',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '国家/地区名称',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态：1启用 0禁用',
  PRIMARY KEY (`id`),
  KEY `idx_code` (`code`),
  KEY `idx_type_id` (`type_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=93 DEFAULT CHARSET=utf8mb4 COMMENT='浏览器语言类型表';

