/*Table structure for table `sk_message` */

DROP TABLE IF EXISTS `sk_message`;

CREATE TABLE `sk_message` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '消息ID',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发件人姓名',
  `email` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发件人邮箱',
  `phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发件人电话',
  `subject` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息主题',
  `content` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息内容',
  `message_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '消息类型（咨询、投诉、建议等）',
  `is_read` tinyint(4) DEFAULT '0' COMMENT '是否已读：0-未读，1-已读',
  `reply_content` longtext COLLATE utf8mb4_unicode_ci COMMENT '回复内容',
  `reply_by` int(10) unsigned DEFAULT NULL COMMENT '回复人ID',
  `replied_at` timestamp NULL DEFAULT NULL COMMENT '回复时间',
  `status` tinyint(4) DEFAULT '1' COMMENT '状态：1-待处理，2-已处理，3-已关闭',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_email` (`email`),
  KEY `idx_is_read` (`is_read`),
  KEY `idx_status` (`status`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='客户留言/消息表';

