/*Table structure for table `sk_product` */

DROP TABLE IF EXISTS `sk_product`;

CREATE TABLE `sk_product` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `category_id` varchar(32) DEFAULT NULL,
  `sub_category` varchar(50) DEFAULT NULL COMMENT '子分类',
  `technical_type` varchar(50) DEFAULT NULL COMMENT '技术类型',
  `value_range` varchar(100) DEFAULT NULL COMMENT '参数范围(如阻值范围)',
  `operating_voltage` varchar(50) DEFAULT NULL COMMENT '工作电压',
  `operating_temperature` varchar(50) DEFAULT NULL COMMENT '工作温度范围',
  `temperature_coefficient` varchar(50) DEFAULT NULL COMMENT '温度系数',
  `subcategory` varchar(100) DEFAULT NULL COMMENT '子分类',
  `rating` varchar(50) DEFAULT 'Catalog' COMMENT '等级：Automotive/Catalog等',
  `temperature_range` varchar(50) DEFAULT NULL COMMENT '工作温度范围（摄氏度）',
  `safety_category` varchar(50) DEFAULT '/' COMMENT '功能安全类别',
  `product_code` varchar(50) DEFAULT NULL,
  `name` varchar(255) NOT NULL,
  `package_type` varchar(50) DEFAULT NULL,
  `pin_count` int(11) DEFAULT '0' COMMENT '引脚数量',
  `stock` int(11) DEFAULT '0' COMMENT '库存数量',
  `normally_stocked` tinyint(4) DEFAULT '0' COMMENT '常备库存：0=否，1=是',
  `rohs_compliant` tinyint(4) DEFAULT '0' COMMENT 'RoHS合规：0=否，1=是',
  `description` text,
  `specs` json DEFAULT NULL,
  `images` json DEFAULT NULL,
  `datasheet_url` varchar(255) DEFAULT NULL,
  `html_url` varchar(255) DEFAULT NULL COMMENT 'HTML链接',
  `status` varchar(10) DEFAULT NULL,
  `is_new` tinyint(4) DEFAULT '0' COMMENT '是否新品：0=否，1=是',
  `views` int(11) DEFAULT '0',
  `sort` int(11) DEFAULT '0',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `product_id` varchar(32) DEFAULT NULL,
  `model_id` int(11) DEFAULT NULL COMMENT '型号ID',
  `model_number` varchar(32) DEFAULT NULL,
  `brand` varchar(32) DEFAULT NULL,
  `image_url` varchar(500) DEFAULT NULL,
  `package_packaging` varchar(50) DEFAULT NULL,
  `inventory_min_order_quantity` int(11) NOT NULL,
  `inventory_lead_time` varchar(50) DEFAULT NULL,
  `pricing_unit_price` decimal(10,2) NOT NULL,
  `pricing_currency` varchar(10) NOT NULL,
  `compliance_rohs` varchar(20) DEFAULT NULL,
  `compliance_reach` varchar(20) DEFAULT NULL,
  `compliance_eccn` varchar(20) DEFAULT NULL,
  `links_datasheet_url` varchar(500) DEFAULT NULL,
  `links_product_page_url` varchar(500) DEFAULT NULL,
  `links_simulation_model_url` varchar(500) DEFAULT NULL,
  `brand_id` int(11) NOT NULL DEFAULT '0',
  `safety_stock` int(11) DEFAULT '0' COMMENT '安全库存',
  `in_transit_stock` int(11) DEFAULT '0' COMMENT '在途库存',
  `category_fk_id` int(11) NOT NULL DEFAULT '0',
  `subcategory_fk_id` int(11) NOT NULL DEFAULT '0',
  `created_at` datetime DEFAULT NULL,
  `price` decimal(8,2) DEFAULT NULL,
  `channels` varchar(10) DEFAULT NULL,
  `bandwidth` varchar(20) DEFAULT NULL,
  `slew_rate` varchar(20) DEFAULT NULL,
  `voltage_range_min` decimal(4,2) DEFAULT NULL,
  `voltage_range_max` decimal(4,2) DEFAULT NULL,
  `offset_voltage` decimal(4,2) DEFAULT NULL,
  `is_on_sale` int(11) DEFAULT '1',
  `features` text COMMENT '特性',
  PRIMARY KEY (`id`),
  UNIQUE KEY `product_code` (`product_code`),
  KEY `idx_subcategory` (`subcategory`),
  KEY `idx_rating` (`rating`),
  KEY `idx_is_new` (`is_new`),
  KEY `idx_stock` (`stock`),
  KEY `idx_normally_stocked` (`normally_stocked`),
  KEY `idx_rohs_compliant` (`rohs_compliant`),
  KEY `idx_model_id` (`model_id`),
  KEY `idx_product_category` (`category_id`),
  KEY `idx_product_brand` (`brand_id`),
  KEY `idx_product_model` (`model_id`),
  KEY `idx_product_status` (`status`),
  CONSTRAINT `fk_product_model` FOREIGN KEY (`model_id`) REFERENCES `sk_product_models` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=1181 DEFAULT CHARSET=utf8mb4 COMMENT='Product Table';

