/*Table structure for table `sk_product_price_break` */

DROP TABLE IF EXISTS `sk_product_price_break`;

CREATE TABLE `sk_product_price_break` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `product_id` varchar(50) NOT NULL,
  `quantity` int(11) NOT NULL COMMENT '数量分界点',
  `price` decimal(10,2) NOT NULL COMMENT '对应单价',
  `currency` varchar(10) DEFAULT NULL,
  `price_unit` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `product_id` (`product_id`),
  KEY `quantity` (`quantity`),
  KEY `idx_pricebreak_product_quantity` (`product_id`,`quantity`)
) ENGINE=InnoDB AUTO_INCREMENT=504 DEFAULT CHARSET=utf8mb4 COMMENT='产品价格区间表';

