/*Table structure for table `sk_product_series` */

DROP TABLE IF EXISTS `sk_product_series`;

CREATE TABLE `sk_product_series` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `series_name` varchar(100) NOT NULL,
  `series_name_en` varchar(100) DEFAULT NULL,
  `description` text,
  `image` varchar(255) DEFAULT NULL,
  `status` tinyint(4) NOT NULL DEFAULT '1',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='Product Series Table';

/*Data for the table `sk_product_series` */

insert  into `sk_product_series`(`id`,`series_name`,`series_name_en`,`description`,`image`,`status`,`create_time`,`update_time`) values 
(1,'PMU系列','PMU Series','电源管理单元系列产品','/images/series/pmu.jpg',1,'2025-12-19 10:00:00','2025-12-19 10:00:00'),
(2,'LDO系列','LDO Series','低压差线性稳压器系列','/images/series/ldo.jpg',1,'2025-12-19 10:00:00','2025-12-19 10:00:00'),
(3,'传感器系列','Sensor Series','各类传感器芯片','/images/series/sensor.jpg',1,'2025-12-19 10:00:00','2025-12-19 10:00:00');

/*Table structure for table `sk_product_spec` */

DROP TABLE IF EXISTS `sk_product_spec`;

CREATE TABLE `sk_product_spec` (
  `spec_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `product_id` varchar(20) DEFAULT NULL,
  `spec_name` varchar(100) DEFAULT NULL,
  `value` varchar(255) NOT NULL,
  `unit` varchar(50) DEFAULT NULL,
  `sort_order` int(11) DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`spec_id`),
  KEY `idx_skps_product_specid` (`product_id`,`spec_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COMMENT='Product Specification Table';

/*Data for the table `sk_product_spec` */

insert  into `sk_product_spec`(`spec_id`,`product_id`,`spec_name`,`value`,`unit`,`sort_order`,`created_at`) values 
(1,'SC1001','输入电压范围','2.7-5.5','V',10,'2025-12-19 10:00:00'),
(2,'SC1001','输出电流','2','A',20,'2025-12-19 10:00:00'),
(3,'SC1002','输入电压范围','1.8-5.5','V',10,'2025-12-19 10:00:00'),
(4,'SC1002','静态电流','1','μA',20,'2025-12-19 10:00:00');

/*Table structure for table `sk_product_specification` */

DROP TABLE IF EXISTS `sk_product_specification`;

CREATE TABLE `sk_product_specification` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `product_id` varchar(100) NOT NULL COMMENT '产品ID',
  `name` varchar(100) NOT NULL COMMENT '参数名称',
  `value` varchar(100) NOT NULL COMMENT '参数值',
  `unit` varchar(20) DEFAULT NULL COMMENT '参数单位',
  `sort_order` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
  PRIMARY KEY (`id`),
  KEY `product_id` (`product_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COMMENT='产品规格参数表';

/*Data for the table `sk_product_specification` */

insert  into `sk_product_specification`(`id`,`product_id`,`name`,`value`,`unit`,`sort_order`) values 
(1,'SC1001','工作温度','-40~85','°C',10),
(2,'SC1001','效率','95','%',20),
(3,'SC1002','工作温度','-40~125','°C',10),
(4,'SC1002','压差电压','0.2','V',20);

/*Table structure for table `sk_product_suppliers` */

DROP TABLE IF EXISTS `sk_product_suppliers`;

CREATE TABLE `sk_product_suppliers` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `product_id` varchar(32) NOT NULL COMMENT '产品ID',
  `supplier_id` int(11) NOT NULL COMMENT '供应商ID',
  `is_primary` tinyint(1) DEFAULT '0' COMMENT '是否主要供应商',
  `supplier_product_code` varchar(100) DEFAULT NULL COMMENT '供应商产品编码',
  `min_order_quantity` int(11) DEFAULT '1' COMMENT '最小起订量',
  `lead_time` varchar(50) DEFAULT NULL COMMENT '供货周期',
  `price` decimal(10,2) DEFAULT NULL COMMENT '价格',
  `currency` varchar(10) DEFAULT 'USD' COMMENT '货币',
  `created_at` datetime DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_product_id` (`product_id`),
  KEY `idx_supplier_id` (`supplier_id`),
  KEY `idx_is_primary` (`is_primary`),
  CONSTRAINT `fk_product_supplier_supplier` FOREIGN KEY (`supplier_id`) REFERENCES `sk_suppliers` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='产品供应商关联表';

/*Data for the table `sk_product_suppliers` */

insert  into `sk_product_suppliers`(`id`,`product_id`,`supplier_id`,`is_primary`,`supplier_product_code`,`min_order_quantity`,`lead_time`,`price`,`currency`,`created_at`,`updated_at`) values 
