/*Table structure for table `sk_visit_log` */

DROP TABLE IF EXISTS `sk_visit_log`;

CREATE TABLE `sk_visit_log` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(10) unsigned DEFAULT NULL,
  `page_url` varchar(255) DEFAULT NULL,
  `ip` varchar(45) DEFAULT NULL,
  `country` varchar(100) DEFAULT NULL,
  `device` varchar(100) DEFAULT NULL,
  `browser` varchar(100) DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Visit Log Table';

/*Data for the table `sk_visit_log` */

/* Procedure structure for procedure `sp_get_category_brands` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_category_brands` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_category_brands`(
    IN p_category_id INT
)
BEGIN
    -- 获取指定分类下有产品的品牌列表
    SELECT DISTINCT 
        b.id,
        b.brand_code,
        b.brand_name,
        b.brand_logo,
        COUNT(p.id) as product_count
    FROM sk_brands b
    JOIN sk_product p ON b.id = p.brand_id
    WHERE p.category_id = p_category_id
      AND p.status = 1
    GROUP BY b.id, b.brand_code, b.brand_name, b.brand_logo
    ORDER BY b.brand_name;
END */$$
DELIMITER ;

